P = [
 dict(pmid='43014970', doi='10.1016/j.jes.2026.03.042', journal='J Environ Sci (China)', title='Significant suppression of sulfur-containing organic aerosols by emission controls during the Hangzhou Asian Games.', short='Hangzhou Asian Games emission controls WSOC FT-ICR MS organosulfate oligomers quasi-natural experiment 2026', design='Filter sampling + composition', pm='PM2.5 water-soluble organic carbon by FT-ICR MS before, during and after the Games', geo='China (Hangzhou)', endpoint='Molecular composition of sulfur-containing organic aerosol', tier='C', basis='Lab / research instrument', affil='Beihang University (Hangzhou International Innovation Institute), China; Beihang University, China', n='Quasi-natural experiment around the 19th Asian Games: WSOC in PM2.5 characterised by ultrahigh-resolution FT-ICR MS across control and post-Games periods. Controls coincided with selective depletion of high-molecular-weight organosulfate oligomers (O10-O13) and highly oxygenated CHOS species, consistent with suppressed acid-catalysed oligomerisation and curtailed ageing; Games-period pollution was dominated by humidity-enhanced aqueous processing, the post-Games rebound by gas-phase oxidation yielding organic dinitrates. No PM2.5 mass change, sample count or uncertainty is given in the abstract, and a single event with co-varying meteorology cannot separate control effects from weather. Relevance: indirect - composition shifts of this kind change optical-sensor response per unit mass, a reason not to transfer calibrations across policy regimes.', sub=corpus.BURD),
 dict(pmid='43014948', doi='10.1016/j.jes.2026.04.026', journal='J Environ Sci (China)', title='Three-dimensional identification of dominant atmospheric pollutants and their sensitivity to soil moisture in northwestern China urban agglomerations.', short='Urumqi-Changji-Shihezi soil moisture PM2.5 PM10 sensitivity threshold CALIOP aerosol typing 3D', design='Statistical analysis of monitoring data', pm='Surface PM2.5 and PM10 against soil moisture; CALIOP aerosol subtypes in 3D', geo='China (Xinjiang)', endpoint='Soil-moisture sensitivity thresholds of PM; vertical aerosol-type frequency', tier='C', basis='Not stated', affil='Xinjiang Normal University, China; Xinjiang Normal University, China', n='Northwest China urban agglomeration: surface PM2.5 and PM10 related to soil moisture, with CALIOP lidar used to map aerosol subtypes in three dimensions. Sensitivity thresholds of both fractions to soil moisture fell at 0.2266-0.2389 m3/m3 (precipitation effects excluded), PM10 being more sensitive. Moist mountain units showed negative PM-moisture correlation (suppressed dust suspension), dry desert and plain units positive correlation (resuspension). Polluted dust dominated below 4 km, polluted continental aerosol below 2 km, with a stable mixed-dust layer aloft. The abstract does not state the PM data source, period or how thresholds were estimated. Relevance: indirect - dust-dominated regimes are where optical low-cost sensors under-read coarse mass; a moisture threshold is a usable covariate for that correction.', sub=corpus.EXPO),
 dict(pmid='43014907', doi='10.1016/j.jes.2026.02.006', journal='J Environ Sci (China)', title='PM2.5-induced liver injury mediated by lipid accumulation via the endoplasmic reticulum stress-related IRE1alpha-XBP1s pathway in mice.', short='Central China Normal mouse 12-week PM2.5 liver lipid accumulation IRE1a-XBP1s ER stress inhibitor', design='Animal exposure study', pm='PM2.5 exposure of mice for 12 weeks at graded concentrations', geo='China (laboratory)', endpoint='Hepatic triglyceride synthesis, liver injury, IRE1a-XBP1s pathway proteins', tier='B', basis='Lab / research instrument', affil='Central China Normal University, China; Central China Normal University, China', n='Mice exposed to PM2.5 for 12 weeks; histopathology, liver-injury markers and proteomics. Lipid accumulation stemmed mainly from triglyceride synthesis; differentially expressed liver proteins clustered in ER processing and fatty-acid metabolism, and IRE1a-XBP1s pathway protein expression rose with PM2.5 concentration. Co-administration of a specific IRE1a-XBP1s inhibitor lowered pathway expression and attenuated both lipid accumulation and liver injury. The abstract gives no exposure concentration, route, particle source or animal numbers, so the dose cannot be placed against human ambient levels, and the inhibitor result supports necessity of the pathway in this model only. Relevance: indirect - adds a hepatic steatosis mechanism to the metabolic arm of PM toxicity; no measurement content.', sub=corpus.MECH),
 dict(pmid='43014905', doi='10.1016/j.jes.2026.03.096', journal='J Environ Sci (China)', title='Revealing the contribution of sulfate-containing particles from industrial emissions to atmospheric environment through CCSEM: Insight into morphology, formation, and transport.', short='Steel plant CCSEM 91185 single particles Na2SO4 sulfate near-source sedimentation transport 6-20 km', design='Field measurement', pm='Individual particles by computer-controlled SEM at five sites inside and around a steel plant', geo='China', endpoint='Particle type, size and number fraction with distance from source', tier='B', basis='Lab / research instrument', affil='Chinese Research Academy of Environmental Sciences, China; Institute of Atmospheric Physics, CAS, China', n='CCSEM classified 91,185 individual particles from five sites within a steel plant and its surroundings. By number, Na-rich (46.6%), Ca-rich (21.5%) and Si-rich (8.2%) particles dominated, spanning 0.2-43.6 um. Elongated submicron Na2SO4 particles made up 72.8% of particles nearest the exhaust outlet, aged rapidly (mean size 1.1 to 3.4 um) with 96.2% depositional removal inside the plant, and fell to 5.3% (2.2-11.7%) at ambient sites 6-20 km away. Number fractions are not mass fractions, a single plant and campaign are shown, and the deposition figure is inferred from composition gradients rather than flux measurement. Relevance: indirect - fenceline sensor networks around steel plants will see a size distribution very different from the urban background they were calibrated in.', sub=corpus.EXPO),
]
